import { HomeAssistant } from './ha_type_stubs';

/**
 * A user's recent credential uses, read from the recorder's history of their
 * credential-used event entity.
 *
 * Each recorded use is one state of that entity: the state is the time of the
 * use and the attributes are the use's payload. Nothing new is stored for
 * this; the history Home Assistant already keeps is read back.
 */

/** How many uses the card lists. */
export const CREDENTIAL_USE_LIMIT = 10;

/** How far back the card asks; the recorder may have kept less. */
const CREDENTIAL_USE_WINDOW_DAYS = 30;

export interface CredentialUse {
    /** Kind of credential presented: `pin`, `rfid`, `fingerprint`, ... */
    credentialType: string;
    /** What the device did: `unlock`, `lock` or `unknown` */
    operation: string;
    /** Entity the credential was used against */
    target: string;
    /** Display name of the target, falling back to its entity ID */
    targetName: string;
    /** When the use was recorded (ISO timestamp, the event entity's state) */
    when: string;
}

/** A state in Home Assistant's compressed history format. */
interface CompressedState {
    a?: Record<string, unknown>;
    s: string;
}

export type HistoryResponse = Record<string, CompressedState[] | undefined>;

const CREDENTIAL_LABELS: Record<string, string> = {
    face: 'Face',
    fingerprint: 'Fingerprint',
    nfc: 'NFC tag',
    password: 'REDACTED',
    pin: 'PIN',
    rfid: 'RFID tag'
};

const OPERATION_LABELS: Record<string, string> = {
    lock: 'Locked',
    unlock: 'Unlocked'
};

/** The history query for one event entity's recent states, attributes included. */
export function buildCredentialUsesQuery(
    eventEntityId: string,
    now: Date = new Date()
): { [key: string]: unknown; type: string } {
    const start = new Date(now.getTime() - CREDENTIAL_USE_WINDOW_DAYS * 24 * 60 * 60 * 1000);
    return {
        entity_ids: [eventEntityId],
        include_start_time_state: false,
        minimal_response: false,
        no_attributes: false,
        // An event entity's state only ever moves forward to the next use's
        // time; asking for every change costs nothing and drops nothing.
        significant_changes_only: false,
        start_time: start.toISOString(),
        type: 'history/history_during_period'
    };
}

/**
 * Turn the history response into uses, newest first.
 *
 * A state that is not a timestamp (`unknown`, `unavailable`) is not a use. A
 * restart writes the last use's state again, so uses are keyed by their time
 * and each is listed once.
 *
 * Only the target is looked up. The source can be a keypad entity whose state
 * is the code that was typed, so it is never read.
 */
export function parseCredentialUses(
    response: HistoryResponse | undefined,
    eventEntityId: string,
    states: HomeAssistant['states'] = {}
): CredentialUse[] {
    const byTime = new Map<string, CredentialUse>();
    for (const row of response?.[eventEntityId] ?? []) {
        if (Number.isNaN(Date.parse(row.s))) continue;
        const attributes = row.a ?? {};
        const target = typeof attributes.target === 'string' ? attributes.target : '';
        const friendlyName = states[target]?.attributes?.friendly_name;
        byTime.set(row.s, {
            credentialType: String(attributes.credential_type ?? attributes.event_type ?? ''),
            operation: String(attributes.operation ?? 'unknown'),
            target,
            targetName: typeof friendlyName === 'string' && friendlyName ? friendlyName : target,
            when: row.s
        });
    }
    return [...byTime.values()]
        .sort((a, b) => Date.parse(b.when) - Date.parse(a.when))
        .slice(0, CREDENTIAL_USE_LIMIT);
}

/** One line saying what was used and, when the device said, what it did. */
export function describeCredentialUse(use: CredentialUse): string {
    const kind = CREDENTIAL_LABELS[use.credentialType] ?? use.credentialType;
    const operation = OPERATION_LABELS[use.operation];
    return operation ? `${kind} · ${operation}` : kind;
}

import { describe, expect, it } from 'vitest';

import {
    CREDENTIAL_USE_LIMIT,
    buildCredentialUsesQuery,
    describeCredentialUse,
    HistoryResponse,
    parseCredentialUses
} from './credential-uses';
import { HomeAssistant } from './ha_type_stubs';

const EVENT = 'event.mock_title_alice_credential_used';

function use(
    when: string,
    target = 'lock.front_door',
    extra: Record<string, unknown> = {}
): { a: Record<string, unknown>; s: string } {
    return {
        a: { credential_type: 'pin', operation: 'unlock', target, ...extra },
        s: when
    };
}

const STATES = {
    'lock.front_door': { attributes: { friendly_name: 'Front Door' }, state: 'locked' }
} as unknown as HomeAssistant['states'];

describe('buildCredentialUsesQuery', () => {
    it('asks for every state of the one entity, attributes included', () => {
        const now = new Date('2026-10-28T12:00:00Z');
        const query = buildCredentialUsesQuery(EVENT, now);
        expect(query).toMatchObject({
            entity_ids: [EVENT],
            minimal_response: false,
            no_attributes: false,
            significant_changes_only: false,
            type: 'history/history_during_period'
        });
        expect(Date.parse(query.start_time as string)).toBeLessThan(now.getTime());
    });
});

describe('parseCredentialUses', () => {
    it('lists uses newest first, naming the target by its friendly name', () => {
        const response: HistoryResponse = {
            [EVENT]: [
                use('2026-10-27T08:00:00.000+00:00'),
                use('2026-10-28T09:00:00.000+00:00', 'cover.side_gate')
            ]
        };
        const uses = parseCredentialUses(response, EVENT, STATES);
        expect(uses.map((u) => u.targetName)).toEqual(['cover.side_gate', 'Front Door']);
        expect(uses[1].when).toBe('2026-10-27T08:00:00.000+00:00');
    });

    it('skips states that are not uses and lists a restored use once', () => {
        const response: HistoryResponse = {
            [EVENT]: [
                { s: 'unknown' },
                use('2026-10-27T08:00:00.000+00:00'),
                { s: 'unavailable' },
                // Home Assistant restarted: the restored state repeats the use.
                use('2026-10-27T08:00:00.000+00:00')
            ]
        };
        expect(parseCredentialUses(response, EVENT, STATES)).toHaveLength(1);
    });

    it('keeps only the most recent uses', () => {
        const rows = Array.from({ length: CREDENTIAL_USE_LIMIT + 5 }, (_, i) =>
            use(new Date(Date.UTC(2026, 9, 1, i)).toISOString())
        );
        const uses = parseCredentialUses({ [EVENT]: rows }, EVENT, STATES);
        expect(uses).toHaveLength(CREDENTIAL_USE_LIMIT);
        expect(uses[0].when).toBe(rows[rows.length - 1].s);
    });

    it('never reads the source, which can hold the typed code', () => {
        const states = {
            ...STATES,
            'sensor.keypad': { attributes: { friendly_name: '4815' }, state: '4815' }
        } as unknown as HomeAssistant['states'];
        const response: HistoryResponse = {
            [EVENT]: [use('2026-10-27T08:00:00.000+00:00', 'lock.front_door', { source: 'sensor.keypad' })]
        };
        const [parsed] = parseCredentialUses(response, EVENT, states);
        expect(JSON.stringify(parsed)).not.toContain('4815');
    });

    it('returns nothing for a missing or empty response', () => {
        expect(parseCredentialUses(undefined, EVENT)).toEqual([]);
        expect(parseCredentialUses({}, EVENT)).toEqual([]);
    });
});

describe('describeCredentialUse', () => {
    it('names the kind and, when known, what the device did', () => {
        const [parsed] = parseCredentialUses(
            { [EVENT]: [use('2026-10-27T08:00:00.000+00:00')] },
            EVENT,
            STATES
        );
        expect(describeCredentialUse(parsed)).toBe('PIN · Unlocked');
        expect(describeCredentialUse({ ...parsed, operation: 'unknown' })).toBe('PIN');
        expect(describeCredentialUse({ ...parsed, credentialType: 'fingerprint', operation: 'lock' })).toBe(
            'Fingerprint · Locked'
        );
    });
});

